export interface TemplateContext {
  appName: string;
  slug: string;
  coreVersion: string;
}

const webPackageName = (context: TemplateContext): string => context.slug + "-web";
const workerPackageName = (context: TemplateContext): string => context.slug + "-worker";
const lines = (values: string[]): string => values.join("\n") + "\n";

export const readme = (context: TemplateContext): string =>
  lines([
    "# " + context.appName,
    "",
    "A ChatGPT-like application generated by @emi/create-chat-app. The generated project owns its",
    "generic web and Worker source, copied from canonical generic fixtures. Only reusable primitives",
    "are imported from @emi/core; no core source is copied.",
    "",
    "## Layout",
    "",
    "web/       Vite + React generic chat application",
    "worker/    Alchemy Cloudflare Worker plus Drizzle schema",
    "",
    "## Getting started",
    "",
    "Add web and worker to a pnpm workspace that resolves @emi/core. Then:",
    "",
    "pnpm install",
    "pnpm --filter " + webPackageName(context) + " typecheck",
    "pnpm --filter " + workerPackageName(context) + " typecheck",
    "pnpm --filter " + workerPackageName(context) + " db:generate",
    "pnpm --filter " + webPackageName(context) + " dev",
    "pnpm --filter " + workerPackageName(context) + " dev",
    "",
    "Only web/src/app-config.ts and worker/src/app-config.ts are generated source configuration.",
    "Every other application file matches generic fixtures and is yours to edit.",
    "",
    "## Deferred",
    "",
    "Real npm publishing of @emi/core is deferred. Until then, dependency version " +
      context.coreVersion +
      " resolves only inside a pnpm workspace containing that package.",
  ]);

export const envExample = (): string =>
  lines([
    "# Copy to .env and fill in secrets for session auth.",
    "# Required for the worker:",
    "#   BETTER_AUTH_SECRET   (min 32 chars)",
    "#   BETTER_AUTH_URL      (public origin, e.g. http://localhost:8787)",
    "# Optional local smoke only (never in production):",
    "#   ALLOW_DEMO_USER_HEADER=1   then send x-demo-user-id on API calls",
    "# Optional branding:",
    "#   AUTH_APP_NAME=Core Chat",
  ]);

export const gitignore = (): string =>
  lines([
    "node_modules",
    "dist",
    ".alchemy",
    ".wrangler",
    "data",
    ".env",
    ".env.*",
    "!.env.example",
  ]);

export const webPackageJson = (context: TemplateContext): string =>
  JSON.stringify(
    {
      name: webPackageName(context),
      version: "0.1.0",
      private: true,
      type: "module",
      scripts: {
        dev: "vite --port 3233",
        build: "vite build",
        typecheck: "tsc --noEmit",
        start: "vite preview --port 3233",
        format: "oxfmt --check",
        "format:fix": "oxfmt",
        lint: "oxlint && oxfmt --check",
        "lint:fix": "oxlint --fix && oxfmt",
      },
      dependencies: {
        "@emi/core": context.coreVersion,
        ai: "catalog:",
        effect: "catalog:",
        react: "^19.2.7",
        "react-dom": "^19.2.7",
      },
      devDependencies: {
        "@types/node": "^26.0.0",
        "@types/react": "^19.2.17",
        "@types/react-dom": "^19.2.3",
        "@vitejs/plugin-react": "^6.0.3",
        oxfmt: "catalog:",
        oxlint: "catalog:",
        typescript: "catalog:",
        vite: "^8.1.4",
      },
    },
    undefined,
    2,
  ) + "\n";

export const webIndexHtml = (context: TemplateContext): string =>
  lines([
    "<!doctype html>",
    '<html lang="en">',
    "  <head>",
    '    <meta charset="UTF-8" />',
    '    <meta name="viewport" content="width=device-width, initial-scale=1.0" />',
    "    <title>" + context.appName + "</title>",
    "  </head>",
    "  <body>",
    '    <div id="root"></div>',
    '    <script type="module" src="/src/main.tsx"></script>',
    "  </body>",
    "</html>",
  ]);

export const webAppConfig = (context: TemplateContext): string =>
  lines([
    "export const genericChatAppConfig = {",
    "  name: " + JSON.stringify(context.appName) + ",",
    '  settingsStorageKey: "chat-settings",',
    '  version: "0.1.0",',
    '  releaseNotes: ["Generic chat foundations are ready for application-specific extensions."],',
    "};",
  ]);

